{"at":"2026-10-09T04:02:19.797Z","phase":"native-file-preview","direction":"receive","value":{"method":"DOM.setChildNodes","params":{"parentId":5,"nodes":[{"nodeId":6,"parentId":5,"backendNodeId":16,"nodeType":1,"nodeName":"A","localName":"a","nodeValue":"","childNodeCount":1,"children":[{"nodeId":7,"parentId":6,"backendNodeId":17,"nodeType":3,"nodeName":"#text","localName":"","nodeValue":"Skip to lesson"}],"attributes":["class","skip-link","href","#main"]},{"nodeId":8,"parentId":5,"backendNodeId":18,"nodeType":1,"nodeName":"HEADER","localName":"header","nodeValue":"","childNodeCount":2,"attributes":["class","topbar"]},{"nodeId":9,"parentId":5,"backendNodeId":19,"nodeType":1,"nodeName":"MAIN","localName":"main","nodeValue":"","childNodeCount":2,"attributes":["id","main","class","layout"]},{"nodeId":10,"parentId":5,"backendNodeId":20,"nodeType":1,"nodeName":"FOOTER","localName":"footer","nodeValue":"","childNodeCount":2,"attributes":[]},{"nodeId":11,"parentId":5,"backendNodeId":21,"nodeType":1,"nodeName":"SCRIPT","localName":"script","nodeValue":"","childNodeCount":1,"children":[{"nodeId":12,"parentId":11,"backendNodeId":22,"nodeType":3,"nodeName":"#text","localName":"","nodeValue":"{\n  \"title\": \"Energy in cells: from light to ATP\",\n  \"license\": \"Original question wording and distractors. Reference textbook content is licensed CC BY-NC-SA 4.0; see the cited OpenStax edition.\",\n  \"attribution\": \"Scientific references: OpenStax, Biology 2e, sections 6.4, 7.1, 7.4 and 8.1–8.3, by Mary Ann Clark, Matthew Douglas and Jung Choi (Rice University). Reference textbook content: CC BY-NC-SA 4.0. Access for free at https://openstax.org/books/biology-2e/pages/1-introduction. Questions and distractors are originally authored for RecallWeave.\",\n  \"concepts\": [\n    \"photosynthesis\",\n    \"glucose\",\n    \"cellular-respiration\",\n    \"atp\"\n  ],\n  \"items\": [\n    {\n      \"id\": \"p1\",\n      \"concept\": \"photosynthesis\",\n      \"prerequisites\": [],\n      \"prompt\": \"A plant has light, water and carbon dioxide, but makes much less chlorophyll. Which direct change is most likely in the light reactions?\",\n      \"options\": [\n        \"Less light energy is absorbed to drive electron transfer\",\n        \"Less carbon dioxide is absorbed directly by chlorophyll\",\n        \"More glucose is split to replace light absorption in photosystems\",\n        \"More oxygen is split to replace chlorophyll's supply of electrons\"\n      ],\n      \"answer\": 0,\n      \"explanation\": \"Chlorophyll absorbs light energy that drives electron transfer in photosynthesis. Making much less chlorophyll reduces this light capture; chlorophyll does not absorb carbon dioxide or split oxygen.\",\n      \"transfer\": \"This links a visible input (light) to the first energy-conversion step.\"\n    },\n    {\n      \"id\": \"p2\",\n      \"concept\": \"photosynthesis\",\n      \"prerequisites\": [],\n      \"prompt\": \"Which statement best describes the role of the Calvin cycle?\",\n      \"options\": [\n        \"It uses ATP and NADPH from light reactions to build carbohydrate from carbon dioxide\",\n        \"It uses chlorophyll to split water and store light energy as NADPH\",\n        \"It breaks glucose into pyruvate and captures energy in ATP and NADH\",\n        \"It transfers electrons to oxygen and uses their energy to generate ATP\"\n      ],\n      \"answer\": 0,\n      \"explanation\": \"The Calvin cycle uses energy carriers produced by the light reactions to fix carbon dioxide into carbohydrate building blocks; it does not capture light directly.\",\n      \"transfer\": \"Keep the two linked stages distinct: light capture supplies chemical energy; carbon fixation uses it.\"\n    },\n    {\n      \"id\": \"g1\",\n      \"concept\": \"glucose\",\n      \"prerequisites\": [\n        \"photosynthesis\"\n      ],\n      \"prompt\": \"A learner says, “Plants get their usable energy from soil.” Which correction best connects photosynthesis to stored chemical energy?\",\n      \"options\": [\n        \"Light supplies energy to build sugars; soil minerals supply nutrients for growth\",\n        \"Soil minerals supply the energy; light supplies the carbon used to build sugars\",\n        \"Carbon dioxide supplies energy; roots absorb the sugars that store that energy\",\n        \"Water supplies the energy; chlorophyll converts soil minerals into sugar molecules\"\n      ],\n      \"answer\": 0,\n      \"explanation\": \"Photosynthesis uses light energy to build energy-rich carbohydrates from carbon dioxide (with water involved in the overall process). Soil minerals support growth but are not the energy source for sugar synthesis.\",\n      \"transfer\": \"Explain the energy path: light → chemical energy in sugars; nutrients and energy are different things.\"\n    },\n    {\n      \"id\": \"r1\",\n      \"concept\": \"cellular-respiration\",\n      \"prerequisites\": [\n        \"glucose\"\n      ],\n      \"prompt\": \"A human muscle cell has glucose available, but oxygen becomes limiting. What is the strongest prediction for its mitochondrial electron transport chain?\",\n      \"options\": [\n        \"Electron flow slows because oxygen is the chain's final electron acceptor\",\n        \"Electron flow increases as glucose replaces oxygen as the final electron acceptor\",\n        \"The chain keeps working normally by passing its electrons to carbon dioxide instead\",\n        \"The chain stops using electrons and makes ATP directly from glucose instead\"\n      ],\n      \"answer\": 0,\n      \"explanation\": \"In aerobic respiration, oxygen accepts electrons at the end of the mitochondrial electron transport chain. Limited oxygen constrains that pathway; cells may use other processes, but those are not the same as aerobic respiration.\",\n      \"transfer\": \"The stored energy in glucose is released through linked pathways; oxygen's role is at the chain's end.\"\n    },\n    {\n      \"id\": \"a1\",\n      \"concept\": \"atp\",\n      \"prerequisites\": [\n        \"cellular-respiration\"\n      ],\n      \"prompt\": \"Why is ATP useful as an immediate energy carrier even though cells store much more energy in fuel molecules?\",\n      \"options\": [\n        \"Its hydrolysis can power cellular work through coupled chemical reactions\",\n        \"It forms a long-term energy store that a cell can use without regenerating it\",\n        \"Its formation releases energy whenever ADP gains another phosphate group\",\n        \"It contains more energy per molecule than glucose and replaces stored fuels\"\n      ],\n      \"answer\": 0,\n      \"explanation\": \"ATP hydrolysis can be coupled to endergonic cellular processes. Cells continually regenerate ATP; it is an immediate transferable energy currency, not a long-term bulk store.\",\n      \"transfer\": \"Distinguish the fuel reservoir (for example, glucose) from the frequently regenerated spendable carrier (ATP).\"\n    },\n    {\n      \"id\": \"x1\",\n      \"concept\": \"atp\",\n      \"prerequisites\": [\n        \"photosynthesis\",\n        \"cellular-respiration\"\n      ],\n      \"prompt\": \"Which comparison best connects photosynthesis and cellular respiration?\",\n      \"options\": [\n        \"Photosynthesis stores captured light energy in sugars; respiration transfers some of that energy to ATP\",\n        \"They run the same chemical reactions in opposite directions inside the same cell compartment\",\n        \"Photosynthesis releases energy from sugars; respiration uses light energy to build those sugars\",\n        \"Photosynthesis and cellular respiration both store light energy, but in different organisms\"\n      ],\n      \"answer\": 0,\n      \"explanation\": \"Photosynthesis stores captured light energy in organic molecules; cellular respiration transfers energy from organic molecules into ATP. The pathways are connected but are not simply identical reverse reactions.\",\n      \"transfer\": \"Use the model to explain why food webs depend on photosynthetic energy capture and why cells need respiration.\"\n    }\n  ]\n}\n"}],"attributes":["id","deck-json","type","application/json"]},{"nodeId":13,"parentId":5,"backendNodeId":23,"nodeType":1,"nodeName":"SCRIPT","localName":"script","nodeValue":"","childNodeCount":1,"children":[{"nodeId":14,"parentId":13,"backendNodeId":24,"nodeType":3,"nodeName":"#text","localName":"","nodeValue":"\n/**\n * Transparent Bayesian Knowledge Tracing and adaptive item selection.\n * Parameters are pedagogical defaults, not fitted or validated estimates.\n * @typedef {{id:string, concept:string, prerequisites:string[], options:string[], answer:number, prompt:string, explanation:string, transfer:string}} Item\n * @typedef {{initial:number, learn:number, guess:number, slip:number}} BktParameters\n */\nconst DEFAULT_BKT = Object.freeze({ initial: 0.22, learn: 0.18, guess: 0.2, slip: 0.1 });\nconst clamp = (value, min = 0, max = 1) => Math.min(max, Math.max(min, value));\n\n/** Bernoulli entropy in bits. @param {number} p */\nfunction entropy(p) {\n  const q = clamp(p);\n  if (q === 0 || q === 1) return 0;\n  return -q * Math.log2(q) - (1 - q) * Math.log2(1 - q);\n}\n\n/**\n * One BKT update. Correctness is evidence, not certainty; a guess and a slip remain possible.\n * @param {number} prior\n * @param {boolean} correct\n * @param {BktParameters} parameters\n */\nfunction updateMastery(prior, correct, parameters = DEFAULT_BKT) {\n  const p = clamp(prior);\n  const { guess, slip, learn } = parameters;\n  for (const [key, value] of Object.entries(parameters)) {\n    if (!Number.isFinite(value) || value < 0 || value > 1) throw new RangeError(`${key} must be in [0,1]`);\n  }\n  const pCorrect = p * (1 - slip) + (1 - p) * guess;\n  const posterior = correct ? p * (1 - slip) / pCorrect : p * slip / (p * slip + (1 - p) * (1 - guess));\n  return clamp(posterior + (1 - posterior) * learn);\n}\n\n/** Expected reduction in uncertainty from an item response under its concept mastery.\n * @param {number} mastery\n * @param {BktParameters} parameters\n */\nfunction expectedInformationGain(mastery, parameters = DEFAULT_BKT) {\n  const p = clamp(mastery);\n  const { guess, slip } = parameters;\n  const pCorrect = p * (1 - slip) + (1 - p) * guess;\n  const correctPosterior = p * (1 - slip) / pCorrect;\n  const wrongPosterior = p * slip / (p * slip + (1 - p) * (1 - guess));\n  return Math.max(0, entropy(p) - pCorrect * entropy(correctPosterior) - (1 - pCorrect) * entropy(wrongPosterior));\n}\n\n/**\n * Select an unseen item maximizing uncertainty reduction plus prerequisite repair.\n * Default ties use the current locale's item-id order. A recorded ID may choose\n * another exact maximum-score tie without changing the default choice.\n * @param {Item[]} items\n * @param {Set<string>} asked\n * @param {Record<string,number>} mastery\n * @param {BktParameters} parameters\n * @param {string} [preferredItemId] recorded identity, honored only at the exact maximum score\n * @returns {Item|null}\n */\nfunction selectNextItem(items, asked, mastery, parameters = DEFAULT_BKT, preferredItemId) {\n  const candidates = items.filter(item => !asked.has(item.id));\n  if (!candidates.length) return null;\n  const score = item => {\n    const m = mastery[item.concept] ?? parameters.initial;\n    // Prefer a weak concept that unlocks several still-unanswered downstream ideas.\n    const downstream = candidates.filter(next => next.id !== item.id && next.prerequisites.includes(item.concept)).length;\n    const prerequisiteRepair = (1 - m) * Math.min(3, downstream) * 0.12;\n    return expectedInformationGain(m, parameters) + prerequisiteRepair;\n  };\n  const selected = candidates.sort((a, b) => score(b) - score(a) || a.id.localeCompare(b.id))[0];\n  if (preferredItemId === undefined) return selected;\n  const preferred = candidates.find(item => item.id === preferredItemId);\n  return preferred && score(preferred) === score(selected) ? preferred : selected;\n}\n\n/** Clone session probabilities so learners' local run has no shared state. */\nfunction initialMastery(concepts, parameters = DEFAULT_BKT) {\n  return Object.fromEntries(concepts.map(concept => [concept, parameters.initial]));\n}\n\n/**\n * Reproducible toy learner run; simulated evidence is never real learner data.\n * @param {Item[]} items\n * @param {string[]} concepts\n * @param {Record<string,number>} latentKnowledge simulated probability of knowing each concept\n * @param {boolean} adaptive use the information-gain selector, or fixed deck order\n * @param {number} seed deterministic pseudo-random seed\n */\nfunction runLearnerSimulation(items, concepts, latentKnowledge, adaptive = true, seed = 20261005) {\n  let state = seed >>> 0 || 1;\n  const random = () => {\n    state ^= state << 13; state ^= state >>> 17; state ^= state << 5;\n    return (state >>> 0) / 4294967296;\n  };\n  const stateByConcept = initialMastery(concepts);\n  const asked = new Set();\n  const trace = [];\n  while (asked.size < items.length) {\n    const item = adaptive ? selectNextItem(items, asked, stateByConcept) : items.find(candidate => !asked.has(candidate.id));\n    const knowledge = clamp(latentKnowledge[item.concept] ?? 0.5);\n    const correct = random() < 0.18 + knowledge * 0.72;\n    asked.add(item.id);\n    stateByConcept[item.concept] = updateMastery(stateByConcept[item.concept], correct);\n    trace.push({ item: item.id, concept: item.concept, correct });\n  }\n  const meanEstimatedMastery = concepts.reduce((sum, concept) => sum + stateByConcept[concept], 0) / concepts.length;\n  return { trace, mastery: stateByConcept, meanEstimatedMastery };\n}\n\n/**\n * A local review snapshot and one bounded practice round.\n * Practice never updates the original answers or the knowledge model.\n */\n\nfunction validChoice(item, choice) {\n  if (!Number.isInteger(choice) || choice < 0 || choice >= item.options.length) {\n    throw new RangeError('Choose one of this question’s answer options.');\n  }\n}\n\n/** Keep the first-attempt order, chosen answer and explanation available for review. */\nfunction createReview(items, answers) {\n  const byId = new Map(items.map(item => [item.id, item]));\n  const seen = new Set();\n  return Object.freeze(answers.map(answer => {\n    const item = byId.get(answer.item);\n    if (!item || seen.has(item.id)) throw new RangeError('Review needs one first answer per known question.');\n    seen.add(item.id);\n    validChoice(item, answer.choice);\n    return Object.freeze({\n      id: item.id,\n      concept: item.concept,\n      prompt: item.prompt,\n      options: Object.freeze([...item.options]),\n      answer: item.answer,\n      choice: answer.choice,\n      correct: answer.choice === item.answer,\n      explanation: item.explanation,\n      transfer: item.transfer\n    });\n  }));\n}\n\n/** Each initially missed question gets one retry, in its original session order. */\nfunction beginPractice(review) {\n  return Object.freeze({\n    items: Object.freeze(review.filter(item => !item.correct)),\n    answers: Object.freeze([])\n  });\n}\n\nfunction currentPracticeItem(round) {\n  return round.items[round.answers.length] ?? null;\n}\n\n/** Return new practice state; both the review and earlier round states stay intact. */\nfunction answerPractice(round, itemId, choice) {\n  const item = currentPracticeItem(round);\n  if (!item || item.id !== itemId) throw new RangeError('Only the current unanswered practice question can be answered.');\n  validChoice(item, choice);\n  return Object.freeze({\n    items: round.items,\n    answers: Object.freeze([...round.answers, Object.freeze({item: item.id, choice, correct: choice === item.answer})])\n  });\n}\n\n/** Learner-authored notes for this session, separate from answers and model state. */\nconst APPLICATION_PROMPT = 'Trace energy from sunlight to a cell doing work. Where does the form of energy change, and what molecule transfers it to cellular processes?';\n\nfunction freezeReflections(notes, application) {\n  return Object.freeze({\n    notes: Object.freeze(notes.map(note => Object.freeze({...note}))),\n    application\n  });\n}\n\nfunction createReflections(items) {\n  const ids = items.map(item => item.id);\n  if (ids.some(id => typeof id !== 'string' || !id.trim()) || new Set(ids).size !== ids.length) {\n    throw new RangeError('Reflections need a distinct identity for every question.');\n  }\n  return freezeReflections(ids.map(item => ({item, text: ''})), '');\n}\n\nfunction itemReflection(reflections, itemId) {\n  const note = reflections.notes.find(note => note.item === itemId);\n  if (!note) throw new RangeError('Choose a question from this session.');\n  return note.text;\n}\n\nfunction updateReflection(reflections, itemId, text) {\n  if (typeof text !== 'string') throw new TypeError('A reflection must be text.');\n  itemReflection(reflections, itemId);\n  return freezeReflections(reflections.notes.map(note =>\n    note.item === itemId ? {item: itemId, text} : note), reflections.application);\n}\n\nfunction updateApplicationReflection(reflections, text) {\n  if (typeof text !== 'string') throw new TypeError('A reflection must be text.');\n  return freezeReflections(reflections.notes, text);\n}\n\n/** Bind exported notes to question identities, regardless of the adaptive review order. */\nfunction reflectionSnapshot(reflections, items) {\n  const expected = createReflections(items);\n  if (!Array.isArray(reflections?.notes) || typeof reflections?.application !== 'string') {\n    throw new RangeError('Study notes need the reflections from this session.');\n  }\n  const byId = new Map();\n  for (const note of reflections.notes) {\n    if (!note || typeof note.item !== 'string' || typeof note.text !== 'string' || byId.has(note.item)) {\n      throw new RangeError('Study notes need one reflection field per question.');\n    }\n    byId.set(note.item, note.text);\n  }\n  if (byId.size !== expected.notes.length || expected.notes.some(note => !byId.has(note.item))) {\n    throw new RangeError('Study notes need the reflections from this session’s questions.');\n  }\n  return freezeReflections(expected.notes.map(({item}) => ({item, text: byId.get(item)})), reflections.application);\n}\n\n\n/** Build local, readable study notes from a completed first session and separate practice. */\nfunction createStudyNotes({ deck, review, mastery, practice = null, reflections = null, exportedAt = new Date(), conceptLabel = id => id, applicationPrompt = APPLICATION_PROMPT }) {\n  if (!Array.isArray(review) || review.length !== deck.items.length || review.length === 0…"}],"attributes":[]}]},"sessionId":"1783152CD58BB56CB99D07608ED732AC"}}
